mapper.update:
UPDATE ip_grade_rule_alert
SET security_short_name = #{securityShortName}
   ,issuer_code = #{issuerCode}
   ,issuer_name = #{issuerName}
   ,current_pool_name = #{currentPoolName}
   ,current_sort = #{currentSort}
   ,fail_reason = #{failReason}
   ,special_type_desc = #{specialTypeDesc}
   ,last_scan_time = #{lastScanTime}
   ,updt_time = #{updtTime}
WHERE id = #{id}

UPDATE ip_grade_rule_alert
SET alert_status = '20'
   ,deal_user_id = #{dealUserId}
   ,deal_user_name = #{dealUserName}
   ,deal_time = #{dealTime}
   ,updt_time = #{updtTime}
WHERE id = #{id}
  AND is_deleted = 0
  AND alert_status = '00'
